import java.util.*;
final class GraphPlan {
    record Pair(int first, int second) {
        Pair {
            if (first > second) {
                int t = first;
                first = second;
                second = t;
            }
        }
    }
    record Action(int number, BitSet pre, BitSet add, BitSet delete) {}
    record Element(Integer number, BitSet pre, BitSet add, BitSet delete) {}
    record MemoKey(int level, List<Integer> goals) {
        MemoKey { goals = List.copyOf(goals); }
    }
    record
        Result(Search.Result search, List<List<Integer>> layers, List<String> lines, int memoHits) {
    }
    interface Frame {}
    static final class ExtractFrame implements Frame {
        int level, stage;
        List<Integer> goals;
        ExtractFrame(int level, List<Integer> goals) {
            this.level = level;
            this.goals = goals;
        }
    }
    static final class AssignFrame implements Frame {
        int level, position, stage, producerIndex;
        List<Integer> goals, chosen, producers;
        AssignFrame(int level, List<Integer> goals, int position, List<Integer> chosen) {
            this.level = level;
            this.goals = goals;
            this.position = position;
            this.chosen = chosen;
        }
    }
    List<Action> actions;
    BitSet goal;
    int limit, searched, memoHits, tried;
    List<BitSet> facts = new ArrayList<>();
    List<Set<Pair>> factMutexes = new ArrayList<>();
    List<List<Element>> elements = new ArrayList<>();
    List<Set<Pair>> elementMutexes = new ArrayList<>();
    List<Map<Integer, List<Integer>>> achievers = new ArrayList<>();
    Set<MemoKey> memo = new HashSet<>();
    List<String> lines = new ArrayList<>();
    GraphPlan(List<Action> actions, BitSet initial, BitSet goal, int limit) {
        this.actions = actions;
        this.goal = goal;
        this.limit = limit;
        facts.add(initial);
        factMutexes.add(new HashSet<>());
    }
    static boolean compatible(BitSet facts, Set<Pair> mutexes) {
        List<Integer> numbers = Grounding.numbers(facts);
        for (int i = 0; i < numbers.size(); i++)
            for (int j = i + 1; j < numbers.size(); j++)
                if (mutexes.contains(new Pair(numbers.get(i), numbers.get(j))))
                    return false;
        return true;
    }
    static boolean conflict(Element first, Element second, Set<Pair> mutexes) {
        if (first.delete().intersects(second.pre()) || first.delete().intersects(second.add()) ||
            second.delete().intersects(first.pre()) || second.delete().intersects(first.add()))
            return true;
        for (int p : Grounding.numbers(first.pre()))
            for (int q : Grounding.numbers(second.pre()))
                if (mutexes.contains(new Pair(p, q)))
                    return true;
        return false;
    }
    void expand(int level) {
        BitSet present = facts.get(level);
        Set<Pair> mutexes = factMutexes.get(level);
        List<Element> available = new ArrayList<>();
        for (Action action : actions)
            if (Grounding.contains(present, action.pre()) && compatible(action.pre(), mutexes))
                available.add(
                    new Element(action.number(), action.pre(), action.add(), action.delete()));
        int actionCount = available.size();
        for (int fact : Grounding.numbers(present)) {
            BitSet singleton = new BitSet();
            singleton.set(fact);
            available.add(new Element(null, singleton, singleton, new BitSet()));
        }
        Set<Pair> exclusive = new HashSet<>();
        for (int first = 0; first < available.size(); first++)
            for (int second = first + 1; second < available.size(); second++)
                if (conflict(available.get(first), available.get(second), mutexes))
                    exclusive.add(new Pair(first, second));
        lines.add("action level " + level + ": actions=" + actionCount +
                  " noops=" + present.cardinality() + " mutexes=" + exclusive.size());
        Map<Integer, List<Integer>> producers = new HashMap<>();
        for (int i = 0; i < available.size(); i++)
            for (int fact : Grounding.numbers(available.get(i).add()))
                producers.computeIfAbsent(fact, k -> new ArrayList<>()).add(i);
        for (List<Integer> list : producers.values())
            list.sort(Comparator.comparingInt(
                i -> available.get(i).number() == null ? -1 : available.get(i).number()));
        BitSet following = new BitSet();
        for (int fact : producers.keySet())
            following.set(fact);
        Set<Pair> followingMutexes = new HashSet<>();
        List<Integer> followingNumbers = Grounding.numbers(following);
        for (int i = 0; i < followingNumbers.size(); i++)
            for (int j = i + 1; j < followingNumbers.size(); j++) {
                int p = followingNumbers.get(i), q = followingNumbers.get(j);
                boolean allExclusive = true;
                for (int x : producers.get(p)) {
                    for (int y : producers.get(q))
                        if (x == y || !exclusive.contains(new Pair(x, y))) {
                            allExclusive = false;
                            break;
                        }
                    if (!allExclusive)
                        break;
                }
                if (allExclusive)
                    followingMutexes.add(new Pair(p, q));
            }
        elements.add(available);
        elementMutexes.add(exclusive);
        achievers.add(producers);
        facts.add(following);
        factMutexes.add(followingMutexes);
    }
    List<List<Integer>> extract(int level, List<Integer> goals) {
        Deque<Frame> stack = new ArrayDeque<>();
        stack.push(new ExtractFrame(level, goals));
        List<List<Integer>> result = null;
        while (!stack.isEmpty()) {
            Frame top = stack.peek();
            if (top instanceof ExtractFrame frame) {
                MemoKey key = new MemoKey(frame.level, frame.goals);
                if (frame.stage == 0) {
                    if (frame.level == 0) {
                        stack.pop();
                        result = List.of();
                        continue;
                    }
                    if (memo.contains(key)) {
                        memoHits++;
                        stack.pop();
                        result = null;
                        continue;
                    }
                    searched++;
                    frame.stage = 1;
                    stack.push(new AssignFrame(frame.level, frame.goals, 0, List.of()));
                } else {
                    if (result == null)
                        memo.add(key);
                    stack.pop();
                }
                continue;
            }
            AssignFrame frame = (AssignFrame)top;
            List<Element> available = elements.get(frame.level - 1);
            if (frame.stage == 0) {
                while (frame.position < frame.goals.size()) {
                    boolean covered = false;
                    for (int chosen : frame.chosen)
                        if (available.get(chosen).add().get(frame.goals.get(frame.position)))
                            covered = true;
                    if (!covered)
                        break;
                    frame.position++;
                }
                if (frame.position == frame.goals.size()) {
                    BitSet previous = new BitSet();
                    for (int chosen : frame.chosen)
                        previous.or(available.get(chosen).pre());
                    frame.stage = 1;
                    stack.push(new ExtractFrame(frame.level - 1, Grounding.numbers(previous)));
                    continue;
                }
                frame.producers =
                    achievers.get(frame.level - 1).get(frame.goals.get(frame.position));
                frame.stage = 2;
            }
            if (frame.stage == 1) {
                if (result != null) {
                    List<Integer> layer = new ArrayList<>();
                    for (int chosen : frame.chosen) {
                        Integer number = available.get(chosen).number();
                        if (number != null)
                            layer.add(number);
                    }
                    layer.sort(Integer::compare);
                    List<List<Integer>> layers = new ArrayList<>(result);
                    layers.add(List.copyOf(layer));
                    result = layers;
                }
                stack.pop();
                continue;
            }
            if (frame.stage == 3) {
                if (result != null) {
                    stack.pop();
                    continue;
                }
                frame.stage = 2;
            }
            boolean pushed = false;
            while (frame.producerIndex < frame.producers.size()) {
                int candidate = frame.producers.get(frame.producerIndex++);
                boolean allowed = true;
                for (int chosen : frame.chosen)
                    if (elementMutexes.get(frame.level - 1).contains(new Pair(candidate, chosen)))
                        allowed = false;
                if (!allowed)
                    continue;
                tried++;
                List<Integer> chosen = new ArrayList<>(frame.chosen);
                chosen.add(candidate);
                frame.stage = 3;
                stack.push(new AssignFrame(frame.level, frame.goals, frame.position + 1, chosen));
                pushed = true;
                break;
            }
            if (!pushed) {
                stack.pop();
                result = null;
            }
        }
        return result;
    }
    Result finish(String status, List<List<Integer>> layers) {
        List<Integer> plan = new ArrayList<>();
        for (List<Integer> layer : layers)
            plan.addAll(layer);
        return new Result(new Search.Result(status, searched, tried, plan), layers, lines,
                          memoHits);
    }
    Result run() {
        for (int level = 0; level <= limit; level++) {
            BitSet present = facts.get(level);
            Set<Pair> mutexes = factMutexes.get(level);
            lines.add("fact level " + level + ": facts=" + present.cardinality() +
                      " mutexes=" + mutexes.size());
            boolean possible = Grounding.contains(present, goal) && compatible(goal, mutexes);
            if (possible) {
                int before = searched, beforeHits = memoHits;
                List<List<Integer>> layers = extract(level, Grounding.numbers(goal));
                lines.add("extract level " + level + ": " + (layers == null ? "fail" : "success") +
                          " searched=" + (searched - before) +
                          " memo_hits=" + (memoHits - beforeHits));
                if (layers != null)
                    return finish("solved", layers);
            } else if (level > 0 && present.cardinality() == facts.get(level - 1).cardinality() &&
                       mutexes.size() == factMutexes.get(level - 1).size())
                return finish("unreachable", List.of());
            if (level == limit)
                return finish("level limit", List.of());
            expand(level);
        }
        throw new IllegalStateException();
    }
}

import java.util.*;
final class Grounding {
    record Action(int number, PddlParser.Schema source, List<String> arguments, int cost,
                  BitSet pre, BitSet neg, BitSet add, BitSet delete) {
        Action { arguments = List.copyOf(arguments); }
        String text() { return new PddlParser.Atom(source.name(), arguments).toString(); }
    }
    record Step(String name, List<String> arguments) {
        Step { arguments = List.copyOf(arguments); }
        public String toString() { return new PddlParser.Atom(name, arguments).toString(); }
    }
    static final class Problem {
        String name;
        PddlParser.Problem source;
        Map<String, List<String>> objectsByType = new LinkedHashMap<>();
        Map<String, int[]> statistics = new LinkedHashMap<>();
        int candidateCount, staticCount;
        List<PddlParser.Atom> facts = new ArrayList<>(), unreachable = new ArrayList<>();
        List<Action> actions = new ArrayList<>();
        BitSet initial = new BitSet(), goal = new BitSet();
        Map<Step, Integer> actionNumbers = new HashMap<>();
        Problem(PddlParser.Problem source) {
            this.source = source;
            name = source.name;
        }
    }
    record Candidate(PddlParser.Schema source, List<String> arguments, Set<PddlParser.Atom> pre,
                     Set<PddlParser.Atom> neg, Set<PddlParser.Atom> add,
                     Set<PddlParser.Atom> delete) {}
    static boolean subtype(Map<String, String> parents, String actual, String expected) {
        for (String type = actual; type != null; type = parents.get(type))
            if (type.equals(expected))
                return true;
        return false;
    }
    static void predicateClasses(PddlParser.Domain domain) {
        domain.fluent.clear();
        for (PddlParser.Schema schema : domain.actions)
            for (PddlParser.Literal literal : schema.effects())
                domain.fluent.add(literal.atom().predicate());
        domain.statics = new HashSet<>(domain.predicates.keySet());
        domain.statics.removeAll(domain.fluent);
    }
    static PddlParser.Atom substitute(PddlParser.Atom atom, Map<String, String> binding) {
        List<String> terms = new ArrayList<>();
        for (String term : atom.terms())
            terms.add(binding.get(term));
        return new PddlParser.Atom(atom.predicate(), terms);
    }
    static boolean contains(BitSet state, BitSet subset) {
        for (int fact = subset.nextSetBit(0); fact >= 0; fact = subset.nextSetBit(fact + 1))
            if (!state.get(fact))
                return false;
        return true;
    }
    static List<Integer> numbers(BitSet bits) {
        List<Integer> result = new ArrayList<>();
        for (int number = bits.nextSetBit(0); number >= 0; number = bits.nextSetBit(number + 1))
            result.add(number);
        return result;
    }
    static BitSet mapped(Set<PddlParser.Atom> atoms, Map<PddlParser.Atom, Integer> numbers) {
        BitSet result = new BitSet();
        for (PddlParser.Atom atom : atoms) {
            Integer number = numbers.get(atom);
            if (number != null)
                result.set(number);
        }
        return result;
    }
    static void enumerate(PddlParser.Domain domain, PddlParser.Problem problem,
                          PddlParser.Schema schema, List<List<String>> choices, int index,
                          List<String> arguments, List<Candidate> candidates, int[] statistics) {
        if (index < choices.size()) {
            for (String object : choices.get(index)) {
                List<String> next = new ArrayList<>(arguments);
                next.add(object);
                enumerate(domain, problem, schema, choices, index + 1, next, candidates,
                          statistics);
            }
            return;
        }
        Map<String, String> binding = new HashMap<>();
        for (int i = 0; i < arguments.size(); i++)
            binding.put(schema.parameters().get(i).name(), arguments.get(i));
        Set<PddlParser.Atom> positive = new HashSet<>(), negative = new HashSet<>();
        Set<PddlParser.Atom> initial = new HashSet<>(problem.initial);
        for (PddlParser.Literal literal : schema.condition()) {
            PddlParser.Atom atom = substitute(literal.atom(), binding);
            boolean truth;
            if (atom.predicate().equals("="))
                truth = atom.terms().getFirst().equals(atom.terms().get(1));
            else if (domain.statics.contains(atom.predicate()))
                truth = initial.contains(atom);
            else {
                (literal.positive() ? positive : negative).add(atom);
                continue;
            }
            if (truth != literal.positive())
                return;
        }
        Set<PddlParser.Atom> adds = new HashSet<>(), deletes = new HashSet<>();
        for (PddlParser.Literal literal : schema.effects())
            (literal.positive() ? adds : deletes).add(substitute(literal.atom(), binding));
        deletes.removeAll(adds);
        candidates.add(
            new Candidate(schema, List.copyOf(arguments), positive, negative, adds, deletes));
        statistics[1]++;
    }
    static Problem ground(PddlParser.Domain domain, PddlParser.Problem source) {
        Problem problem = new Problem(source);
        for (String type : domain.typeOrder) {
            List<String> objects = new ArrayList<>();
            for (var entry : source.objects.entrySet())
                if (subtype(domain.parents, entry.getValue(), type))
                    objects.add(entry.getKey());
            problem.objectsByType.put(type, objects);
        }
        List<Candidate> candidates = new ArrayList<>();
        for (PddlParser.Schema schema : domain.actions) {
            List<List<String>> choices = new ArrayList<>();
            int assignments = 1;
            for (PddlParser.Typed parameter : schema.parameters()) {
                List<String> objects = problem.objectsByType.get(parameter.type());
                choices.add(objects);
                assignments *= objects.size();
            }
            int[] stats = {assignments, 0, 0};
            problem.statistics.put(schema.name(), stats);
            enumerate(domain, source, schema, choices, 0, List.of(), candidates, stats);
        }
        problem.candidateCount = candidates.size();
        Set<PddlParser.Atom> reachable = new HashSet<>();
        for (PddlParser.Atom atom : source.initial)
            if (domain.fluent.contains(atom.predicate()))
                reachable.add(atom);
        boolean[] accepted = new boolean[candidates.size()];
        boolean changed = true;
        while (changed) {
            changed = false;
            for (int i = 0; i < candidates.size(); i++) {
                Candidate candidate = candidates.get(i);
                if (!accepted[i] && reachable.containsAll(candidate.pre())) {
                    accepted[i] = true;
                    reachable.addAll(candidate.add());
                    problem.statistics.get(candidate.source().name())[2]++;
                    changed = true;
                }
            }
        }
        Map<String, Integer> predicateOrder = new HashMap<>(), objectOrder = new HashMap<>();
        int index = 0;
        for (String predicate : domain.predicates.keySet())
            predicateOrder.put(predicate, index++);
        index = 0;
        for (String object : source.objects.keySet())
            objectOrder.put(object, index++);
        problem.facts = new ArrayList<>(reachable);
        problem.facts.sort((a, b) -> {
            int c = Integer.compare(predicateOrder.get(a.predicate()),
                                    predicateOrder.get(b.predicate()));
            if (c != 0)
                return c;
            for (int i = 0; i < a.terms().size(); i++) {
                c = Integer.compare(objectOrder.get(a.terms().get(i)),
                                    objectOrder.get(b.terms().get(i)));
                if (c != 0)
                    return c;
            }
            return 0;
        });
        Map<PddlParser.Atom, Integer> factNumbers = new HashMap<>();
        for (int i = 0; i < problem.facts.size(); i++)
            factNumbers.put(problem.facts.get(i), i);
        for (int i = 0; i < candidates.size(); i++)
            if (accepted[i]) {
                Candidate c = candidates.get(i);
                Action action =
                    new Action(problem.actions.size(), c.source(), c.arguments(), c.source().cost(),
                               mapped(c.pre(), factNumbers), mapped(c.neg(), factNumbers),
                               mapped(c.add(), factNumbers), mapped(c.delete(), factNumbers));
                problem.actions.add(action);
                problem.actionNumbers.put(new Step(action.source().name(), action.arguments()),
                                          action.number());
            }
        Set<PddlParser.Atom> initialAtoms = new HashSet<>(source.initial);
        for (PddlParser.Atom atom : source.initial)
            if (domain.fluent.contains(atom.predicate()))
                problem.initial.set(factNumbers.get(atom));
            else
                problem.staticCount++;
        for (PddlParser.Atom atom : source.goals) {
            Integer number = factNumbers.get(atom);
            if (number != null)
                problem.goal.set(number);
            else if (!domain.statics.contains(atom.predicate()) || !initialAtoms.contains(atom))
                problem.unreachable.add(atom);
        }
        return problem;
    }
}

import java.util.*;
final class Heuristics {
    static final int INF = -1;
    static final List<String> NAMES = List.of("goalcount", "hmax", "hadd", "ff", "lmcount");
    record Levels(int[] facts, int[] actions) {}
    Grounding.Problem problem;
    List<List<Integer>> achievers = new ArrayList<>();
    Map<BitSet, int[]> maxCosts = new HashMap<>(), addCosts = new HashMap<>();
    Map<BitSet, List<Integer>> relaxedCache = new HashMap<>();
    Map<BitSet, Levels> levelsCache = new HashMap<>();
    Map<BitSet, BitSet> landmarkCache = new HashMap<>();
    Heuristics(Grounding.Problem problem) {
        this.problem = problem;
        for (PddlParser.Atom fact : problem.facts)
            achievers.add(new ArrayList<>());
        for (Grounding.Action action : problem.actions)
            for (int fact : Grounding.numbers(action.add()))
                achievers.get(fact).add(action.number());
    }
    int[] relaxedCosts(BitSet state, boolean maximum) {
        Map<BitSet, int[]> cache = maximum ? maxCosts : addCosts;
        int[] cached = cache.get(state);
        if (cached != null)
            return cached;
        int[] costs = new int[problem.facts.size()];
        Arrays.fill(costs, INF);
        for (int fact : Grounding.numbers(state))
            costs[fact] = 0;
        boolean changed = true;
        while (changed) {
            changed = false;
            for (Grounding.Action action : problem.actions) {
                int aggregate = 0;
                boolean finite = true;
                for (int fact : Grounding.numbers(action.pre())) {
                    if (costs[fact] == INF) {
                        finite = false;
                        break;
                    }
                    aggregate =
                        maximum ? Math.max(aggregate, costs[fact]) : aggregate + costs[fact];
                }
                if (!finite)
                    continue;
                int value = action.cost() + aggregate;
                for (int fact : Grounding.numbers(action.add()))
                    if (costs[fact] == INF || value < costs[fact]) {
                        costs[fact] = value;
                        changed = true;
                    }
            }
        }
        cache.put(state, costs);
        return costs;
    }
    List<Integer> relaxedPlan(BitSet state) {
        if (relaxedCache.containsKey(state))
            return relaxedCache.get(state);
        int[] costs = relaxedCosts(state, false);
        for (int goal : Grounding.numbers(problem.goal))
            if (costs[goal] == INF) {
                relaxedCache.put(state, null);
                return null;
            }
        Set<Integer> chosen = new TreeSet<>();
        Deque<Integer> pending = new ArrayDeque<>();
        for (int goal : Grounding.numbers(problem.goal))
            if (!state.get(goal))
                pending.add(goal);
        while (!pending.isEmpty()) {
            int fact = pending.removeLast(), winner = -1, lowest = INF;
            for (int number : achievers.get(fact)) {
                Grounding.Action action = problem.actions.get(number);
                int cost = action.cost();
                boolean finite = true;
                for (int pre : Grounding.numbers(action.pre())) {
                    if (costs[pre] == INF) {
                        finite = false;
                        break;
                    }
                    cost += costs[pre];
                }
                if (finite && (lowest == INF || cost < lowest)) {
                    lowest = cost;
                    winner = number;
                }
            }
            if (chosen.add(winner))
                for (int pre : Grounding.numbers(problem.actions.get(winner).pre()))
                    if (!state.get(pre))
                        pending.add(pre);
        }
        List<Integer> result = List.copyOf(chosen);
        relaxedCache.put(state, result);
        return result;
    }
    List<Integer> helpful(BitSet state) {
        List<Integer> result = new ArrayList<>(), plan = relaxedPlan(state);
        if (plan != null)
            for (int number : plan)
                if (Search.applicable(problem.actions.get(number), state))
                    result.add(number);
        return result;
    }
    Levels levels(BitSet state) {
        Levels cached = levelsCache.get(state);
        if (cached != null)
            return cached;
        int[] facts = new int[problem.facts.size()], actions = new int[problem.actions.size()];
        Arrays.fill(facts, INF);
        Arrays.fill(actions, INF);
        for (int fact : Grounding.numbers(state))
            facts[fact] = 0;
        int level = 0;
        while (true) {
            boolean changed = false;
            for (Grounding.Action action : problem.actions) {
                if (actions[action.number()] != INF)
                    continue;
                boolean available = true;
                for (int pre : Grounding.numbers(action.pre()))
                    if (facts[pre] == INF || facts[pre] > level)
                        available = false;
                if (!available)
                    continue;
                actions[action.number()] = level;
                for (int fact : Grounding.numbers(action.add()))
                    if (facts[fact] == INF) {
                        facts[fact] = level + 1;
                        changed = true;
                    }
            }
            if (!changed)
                break;
            level++;
        }
        Levels result = new Levels(facts, actions);
        levelsCache.put(state, result);
        return result;
    }
    boolean verified(BitSet state, int excluded) {
        BitSet reachable = (BitSet)state.clone();
        boolean changed = true;
        while (changed) {
            changed = false;
            for (Grounding.Action action : problem.actions)
                if (!action.add().get(excluded) && Grounding.contains(reachable, action.pre())) {
                    int before = reachable.cardinality();
                    reachable.or(action.add());
                    if (reachable.cardinality() != before)
                        changed = true;
                }
        }
        return !Grounding.contains(reachable, problem.goal);
    }
    BitSet landmarks(BitSet state) {
        if (landmarkCache.containsKey(state))
            return landmarkCache.get(state);
        Levels levels = levels(state);
        for (int goal : Grounding.numbers(problem.goal))
            if (levels.facts()[goal] == INF) {
                landmarkCache.put(state, null);
                return null;
            }
        BitSet landmarks = (BitSet)problem.goal.clone();
        landmarks.andNot(state);
        Deque<Integer> pending = new ArrayDeque<>(Grounding.numbers(landmarks));
        Map<Integer, Boolean> verification = new HashMap<>();
        while (!pending.isEmpty()) {
            int fact = pending.remove();
            BitSet candidates = null;
            for (int number : achievers.get(fact))
                if (levels.actions()[number] == levels.facts()[fact] - 1) {
                    if (candidates == null)
                        candidates = (BitSet)problem.actions.get(number).pre().clone();
                    else
                        candidates.and(problem.actions.get(number).pre());
                }
            candidates.andNot(state);
            candidates.andNot(landmarks);
            for (int candidate : Grounding.numbers(candidates))
                if (verification.computeIfAbsent(candidate, key -> verified(state, key))) {
                    landmarks.set(candidate);
                    pending.add(candidate);
                }
        }
        landmarkCache.put(state, landmarks);
        return landmarks;
    }
    int value(String name, BitSet state) {
        if (name.equals("none"))
            return 0;
        if (name.equals("goalcount")) {
            BitSet remaining = (BitSet)problem.goal.clone();
            remaining.andNot(state);
            return remaining.cardinality();
        }
        if (name.equals("hmax") || name.equals("hadd")) {
            boolean maximum = name.equals("hmax");
            int[] costs = relaxedCosts(state, maximum);
            int result = 0;
            for (int goal : Grounding.numbers(problem.goal)) {
                if (costs[goal] == INF)
                    return INF;
                result = maximum ? Math.max(result, costs[goal]) : result + costs[goal];
            }
            return result;
        }
        if (name.equals("ff")) {
            List<Integer> plan = relaxedPlan(state);
            if (plan == null)
                return INF;
            int total = 0;
            for (int number : plan)
                total += problem.actions.get(number).cost();
            return total;
        }
        BitSet landmarks = landmarks(state);
        return landmarks == null ? INF : landmarks.cardinality();
    }
    int[] values(BitSet state) {
        int[] result = new int[NAMES.size()];
        for (int i = 0; i < result.length; i++)
            result[i] = value(NAMES.get(i), state);
        return result;
    }
}

import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
public final class Main {
    record Run(String algorithm, String heuristic) {
        String tag() { return algorithm + " " + heuristic; }
    }
    static final class Settings {
        int budget, weight, graphplan;
        List<Run> runs = new ArrayList<>();
        Run repair;
        Settings(String text) {
            for (String line : text.split("\n")) {
                if (line.isEmpty() || line.startsWith("#"))
                    continue;
                String[] f = line.split(" ");
                switch (f[0]) {
                case "budget":
                    budget = Integer.parseInt(f[1]);
                    break;
                case "weight":
                    weight = Integer.parseInt(f[1]);
                    break;
                case "graphplan":
                    graphplan = Integer.parseInt(f[1]);
                    break;
                case "run":
                    runs.add(new Run(f[1], f[2]));
                    break;
                case "repair":
                    repair = new Run(f[1], f[2]);
                    break;
                }
            }
        }
    }
    static final class Candidate {
        int number;
        String problem, label;
        List<Grounding.Step> steps = new ArrayList<>();
        Candidate(int number, String problem, String label) {
            this.number = number;
            this.problem = problem;
            this.label = label;
        }
    }
    record Validation(String status, List<String> messages, int correct) {
        String verdict() {
            return status + (status.equals("valid") ? " " : ": ") + messages.getFirst();
        }
    }
    record Transformed(List<GraphPlan.Action> actions, BitSet initial, int complements) {}
    record Summary(int solved, Integer best, String optimal) {}
    static final class Totals {
        int solved, best, expanded, generated;
    }
    static String read(String name) throws Exception {
        return Files.readString(Path.of("input", name), StandardCharsets.US_ASCII);
    }
    static List<Candidate> readCandidates(String text) {
        List<Candidate> candidates = new ArrayList<>();
        Candidate current = null;
        for (String line : text.split("\n")) {
            if (line.isEmpty() || line.startsWith("#"))
                continue;
            if (line.startsWith("plan ")) {
                String[] f = line.split(" ");
                current = new Candidate(candidates.size() + 1, f[1], f[2]);
            } else if (line.equals("end")) {
                candidates.add(current);
                current = null;
            } else {
                String[] f = line.substring(1, line.length() - 1).split(" ");
                current.steps.add(new Grounding.Step(f[0], Arrays.asList(f).subList(1, f.length)));
            }
        }
        return candidates;
    }
    static String headed(String heading, List<String> items) {
        return heading + " " + (items.isEmpty() ? "-" : String.join(" ", items));
    }
    static String numberList(BitSet numbers) {
        List<String> values = new ArrayList<>();
        for (int number : Grounding.numbers(numbers))
            values.add(Integer.toString(number));
        return values.isEmpty() ? "-" : String.join(",", values);
    }
    static String valueText(int value) {
        return value == Heuristics.INF ? "inf" : Integer.toString(value);
    }
    static String heuristicText(int[] values) {
        List<String> items = new ArrayList<>();
        for (int i = 0; i < Heuristics.NAMES.size(); i++)
            items.add(Heuristics.NAMES.get(i) + "=" + valueText(values[i]));
        return String.join(" ", items);
    }
    static String argumentError(PddlParser.Domain domain, List<String> arguments,
                                List<String> expected, Map<String, String> table, String noun) {
        if (arguments.size() != expected.size())
            return "expected " + expected.size() + " arguments, got " + arguments.size();
        for (int i = 0; i < arguments.size(); i++) {
            String argument = arguments.get(i), type = table.get(argument);
            if (type == null)
                return "unknown " + noun + " " + argument;
            if (!Grounding.subtype(domain.parents, type, expected.get(i)))
                return "argument " + (i + 1) + " (" + argument + ") is not of type " +
                    expected.get(i);
        }
        return null;
    }
    static void validateDomain(PddlParser.Domain domain) {
        List<PddlParser.Schema> kept = new ArrayList<>();
        for (PddlParser.Schema action : domain.actions) {
            String error = null;
            Map<String, String> parameters = new HashMap<>();
            for (PddlParser.Typed parameter : action.parameters()) {
                parameters.put(parameter.name(), parameter.type());
                if (!domain.parents.containsKey(parameter.type()) && error == null)
                    error = "unknown type " + parameter.type();
            }
            if (error == null) {
                List<PddlParser.Literal> literals = new ArrayList<>(action.condition());
                literals.addAll(action.effects());
                for (PddlParser.Literal literal : literals) {
                    PddlParser.Atom atom = literal.atom();
                    if (!atom.predicate().equals("=") &&
                        !domain.predicates.containsKey(atom.predicate()))
                        error = "unknown predicate " + atom.predicate();
                    else
                        error = argumentError(domain, atom.terms(),
                                              atom.predicate().equals("=")
                                                  ? List.of("object", "object")
                                                  : domain.predicates.get(atom.predicate()),
                                              parameters, "variable");
                    if (error != null) {
                        error = atom + ": " + error;
                        break;
                    }
                }
            }
            if (error == null) {
                kept.add(action);
                domain.byName.put(action.name(), action);
            } else
                domain.diagnostics.add("error: action " + action.name() + ": " + error);
        }
        domain.actions = kept;
        Set<String> used = new HashSet<>();
        for (PddlParser.Schema action : kept) {
            for (PddlParser.Literal literal : action.condition())
                used.add(literal.atom().predicate());
            for (PddlParser.Literal literal : action.effects())
                used.add(literal.atom().predicate());
        }
        for (String predicate : domain.predicates.keySet())
            if (!used.contains(predicate))
                domain.diagnostics.add("warning: predicate " + predicate +
                                       " is not used by any action");
        Grounding.predicateClasses(domain);
    }
    static List<PddlParser.Atom> validateAtoms(PddlParser.Domain domain, PddlParser.Problem problem,
                                               List<PddlParser.Atom> atoms, String side) {
        List<PddlParser.Atom> kept = new ArrayList<>();
        Set<PddlParser.Atom> seen = new HashSet<>();
        for (PddlParser.Atom atom : atoms) {
            String error =
                domain.predicates.containsKey(atom.predicate())
                    ? argumentError(domain, atom.terms(), domain.predicates.get(atom.predicate()),
                                    problem.objects, "object")
                    : "unknown predicate " + atom.predicate();
            if (error == null && seen.contains(atom))
                error = "duplicate";
            if (error == null) {
                kept.add(atom);
                seen.add(atom);
            } else
                problem.diagnostics.add("warning: " + side + " " + atom + ": " + error);
        }
        return kept;
    }
    static void validateProblem(PddlParser.Domain domain, PddlParser.Problem problem) {
        problem.initial = validateAtoms(domain, problem, problem.initial, "init");
        problem.goals = validateAtoms(domain, problem, problem.goals, "goal");
    }
    static Validation validateSteps(PddlParser.Domain domain, PddlParser.Problem problem,
                                    List<Grounding.Step> steps) {
        Set<PddlParser.Atom> world = new HashSet<>(problem.initial);
        int cost = 0;
        for (int i = 0; i < steps.size(); i++) {
            Grounding.Step step = steps.get(i);
            String heading = "step " + (i + 1) + " " + step + ": ";
            PddlParser.Schema schema = domain.byName.get(step.name());
            if (schema == null)
                return new Validation("invalid", List.of(heading + "unknown action " + step.name()),
                                      i);
            List<String> expected = new ArrayList<>();
            for (PddlParser.Typed parameter : schema.parameters())
                expected.add(parameter.type());
            String error =
                argumentError(domain, step.arguments(), expected, problem.objects, "object");
            if (error != null)
                return new Validation("invalid", List.of(heading + error), i);
            Map<String, String> assignment = new HashMap<>();
            for (int p = 0; p < schema.parameters().size(); p++)
                assignment.put(schema.parameters().get(p).name(), step.arguments().get(p));
            for (PddlParser.Literal literal : schema.condition()) {
                PddlParser.Atom bound = Grounding.substitute(literal.atom(), assignment);
                boolean truth = bound.predicate().equals("=")
                                    ? bound.terms().getFirst().equals(bound.terms().get(1))
                                    : world.contains(bound);
                if (truth != literal.positive())
                    return new Validation(
                        "invalid",
                        List.of(heading + "precondition " +
                                (literal.positive() ? bound.toString() : "(not " + bound + ")") +
                                " is false"),
                        i);
            }
            Set<PddlParser.Atom> deletes = new HashSet<>(), adds = new HashSet<>();
            for (PddlParser.Literal literal : schema.effects())
                (literal.positive() ? adds : deletes)
                    .add(Grounding.substitute(literal.atom(), assignment));
            world.removeAll(deletes);
            world.addAll(adds);
            cost += schema.cost();
        }
        List<String> missing = new ArrayList<>();
        for (PddlParser.Atom atom : problem.goals)
            if (!world.contains(atom))
                missing.add("unsatisfied goal " + atom);
        return missing.isEmpty()
            ? new Validation("valid", List.of("length=" + steps.size() + " cost=" + cost),
                             steps.size())
            : new Validation("goal not reached", missing, steps.size());
    }
    static List<Grounding.Step> planSteps(Grounding.Problem problem, List<Integer> plan) {
        List<Grounding.Step> steps = new ArrayList<>();
        for (int number : plan) {
            Grounding.Action action = problem.actions.get(number);
            steps.add(new Grounding.Step(action.source().name(), action.arguments()));
        }
        return steps;
    }
    static int planCost(Grounding.Problem problem, List<Integer> plan) {
        int cost = 0;
        for (int number : plan)
            cost += problem.actions.get(number).cost();
        return cost;
    }
    static boolean interferes(Grounding.Action first, Grounding.Action second) {
        return first.delete().intersects(second.pre()) || first.delete().intersects(second.add()) ||
            second.delete().intersects(first.pre()) || second.delete().intersects(first.add()) ||
            first.add().intersects(second.neg()) || second.add().intersects(first.neg());
    }
    static List<List<Integer>> parallelize(Grounding.Problem problem, List<Integer> plan) {
        List<Integer> assigned = new ArrayList<>();
        List<List<Integer>> layers = new ArrayList<>();
        for (int position = 0; position < plan.size(); position++) {
            Grounding.Action action = problem.actions.get(plan.get(position));
            int layer = 1;
            for (int earlier = 0; earlier < position; earlier++) {
                Grounding.Action previous = problem.actions.get(plan.get(earlier));
                if (previous.add().intersects(action.pre()) ||
                    previous.delete().intersects(action.neg()) || interferes(previous, action))
                    layer = Math.max(layer, assigned.get(earlier) + 1);
            }
            assigned.add(layer);
            while (layers.size() < layer)
                layers.add(new ArrayList<>());
            layers.get(layer - 1).add(action.number());
        }
        return layers;
    }
    static String validateParallel(Grounding.Problem problem, List<List<Integer>> layers) {
        BitSet state = problem.initial;
        for (int k = 0; k < layers.size(); k++) {
            List<Integer> layer = layers.get(k);
            for (int number : layer)
                if (!Search.applicable(problem.actions.get(number), state))
                    return "invalid at layer " + (k + 1);
            for (int i = 0; i < layer.size(); i++)
                for (int j = i + 1; j < layer.size(); j++)
                    if (interferes(problem.actions.get(layer.get(i)),
                                   problem.actions.get(layer.get(j))))
                        return "invalid at layer " + (k + 1);
            BitSet deletes = new BitSet(), adds = new BitSet();
            for (int number : layer) {
                deletes.or(problem.actions.get(number).delete());
                adds.or(problem.actions.get(number).add());
            }
            BitSet next = (BitSet)state.clone();
            next.andNot(deletes);
            next.or(adds);
            state = next;
        }
        return Grounding.contains(state, problem.goal) ? "valid" : "goal not reached";
    }
    static List<Integer> improve(Grounding.Problem problem, List<Integer> plan) {
        List<Integer> sequence = new ArrayList<>(plan);
        int position = 0;
        while (position < sequence.size()) {
            BitSet state = problem.initial;
            for (int i = 0; i < position; i++)
                state = Search.apply(problem.actions.get(sequence.get(i)), state);
            List<Integer> applied = new ArrayList<>();
            for (int i = position + 1; i < sequence.size(); i++) {
                Grounding.Action action = problem.actions.get(sequence.get(i));
                if (Search.applicable(action, state)) {
                    state = Search.apply(action, state);
                    applied.add(action.number());
                }
            }
            if (Grounding.contains(state, problem.goal)) {
                List<Integer> next = new ArrayList<>(sequence.subList(0, position));
                next.addAll(applied);
                sequence = next;
            } else
                position++;
        }
        return sequence;
    }
    static BitSet reachedLandmarks(Grounding.Problem problem, List<Integer> plan,
                                   BitSet landmarks) {
        BitSet state = problem.initial, reached = new BitSet();
        for (int number : plan) {
            state = Search.apply(problem.actions.get(number), state);
            BitSet present = (BitSet)state.clone();
            present.and(landmarks);
            reached.or(present);
        }
        return reached;
    }
    static Transformed transformNegatives(Grounding.Problem problem) {
        BitSet negative = new BitSet();
        for (Grounding.Action action : problem.actions)
            negative.or(action.neg());
        Map<Integer, Integer> complements = new HashMap<>();
        for (int fact : Grounding.numbers(negative))
            complements.put(fact, problem.facts.size() + complements.size());
        List<GraphPlan.Action> actions = new ArrayList<>();
        for (Grounding.Action action : problem.actions) {
            BitSet pre = (BitSet)action.pre().clone(), add = (BitSet)action.add().clone(),
                   delete = (BitSet)action.delete().clone();
            for (int fact : Grounding.numbers(action.neg()))
                pre.set(complements.get(fact));
            for (int fact : Grounding.numbers(action.delete()))
                if (complements.containsKey(fact))
                    add.set(complements.get(fact));
            for (int fact : Grounding.numbers(action.add()))
                if (complements.containsKey(fact))
                    delete.set(complements.get(fact));
            actions.add(new GraphPlan.Action(action.number(), pre, add, delete));
        }
        BitSet initial = (BitSet)problem.initial.clone();
        for (int fact : Grounding.numbers(negative))
            if (!initial.get(fact))
                initial.set(complements.get(fact));
        return new Transformed(actions, initial, complements.size());
    }
    static final class Planner {
        PddlParser.Domain domain;
        List<PddlParser.Problem> sources;
        Settings settings;
        List<Candidate> candidates;
        List<String> tags = new ArrayList<>();
        List<Totals> totals = new ArrayList<>();
        List<String> groundingLines = new ArrayList<>(), planLines = new ArrayList<>(),
                     graphLines = new ArrayList<>(), validationLines = new ArrayList<>(),
                     comparisonLines = new ArrayList<>();
        Map<String, Grounding.Problem> problems = new LinkedHashMap<>();
        Map<String, Heuristics> evaluators = new HashMap<>();
        Map<String, Summary> summaries = new LinkedHashMap<>();
        int validatedPlans, validPlans, validCandidates;
        Planner() throws Exception {
            domain = PddlParser.readDomain(read("domain.txt"));
            sources = PddlParser.readProblems(read("problems.txt"));
            settings = new Settings(read("params.txt"));
            candidates = readCandidates(read("candidates.txt"));
            validateDomain(domain);
            for (Run run : settings.runs)
                tags.add(run.tag());
            tags.add("graphplan");
            for (String tag : tags)
                totals.add(new Totals());
            comparisonLines.add("problem,algorithm,heuristic,length,cost,expanded,generated");
        }
        List<String> actionTexts(Grounding.Problem problem, List<Integer> plan) {
            List<String> text = new ArrayList<>();
            for (int number : plan)
                text.add(problem.actions.get(number).text());
            return text;
        }
        void domainReport() {
            groundingLines.add("== domain " + domain.name + " ==");
            groundingLines.addAll(domain.diagnostics);
            for (String type : domain.typeOrder) {
                List<String> chain = new ArrayList<>();
                for (String current = type; current != null; current = domain.parents.get(current))
                    chain.add(current);
                groundingLines.add("type " + String.join(" < ", chain));
            }
            for (var entry : domain.predicates.entrySet())
                groundingLines.add("predicate " + entry.getKey() + "/" + entry.getValue().size() +
                                   " " +
                                   (domain.fluent.contains(entry.getKey()) ? "fluent" : "static"));
            for (PddlParser.Schema action : domain.actions) {
                int adds = 0, deletes = 0;
                for (PddlParser.Literal literal : action.effects())
                    if (literal.positive())
                        adds++;
                    else
                        deletes++;
                groundingLines.add("action " + action.name() + "/" + action.parameters().size() +
                                   " cost=" + action.cost() + " pre=" + action.condition().size() +
                                   " add=" + adds + " del=" + deletes);
            }
        }
        void groundingReport(Grounding.Problem problem) {
            groundingLines.add("");
            groundingLines.add("== problem " + problem.name + " ==");
            groundingLines.addAll(problem.source.diagnostics);
            groundingLines.add("objects: " + problem.source.objects.size());
            for (String type : domain.typeOrder)
                groundingLines.add(headed("  " + type + ":", problem.objectsByType.get(type)));
            groundingLines.add("static facts: " + problem.staticCount);
            for (PddlParser.Schema action : domain.actions) {
                int[] statistics = problem.statistics.get(action.name());
                groundingLines.add("schema " + action.name() + ": assignments=" + statistics[0] +
                                   " candidates=" + statistics[1] + " reachable=" + statistics[2]);
            }
            groundingLines.add("candidates: " + problem.candidateCount +
                               " reachable: " + problem.actions.size());
            groundingLines.add("facts: " + problem.facts.size() +
                               " init: " + problem.initial.cardinality() +
                               " goals: " + problem.goal.cardinality());
            for (PddlParser.Atom atom : problem.unreachable)
                groundingLines.add("unreachable goal: " + atom);
            Map<String, Integer> counts = new HashMap<>();
            for (PddlParser.Atom fact : problem.facts)
                counts.merge(fact.predicate(), 1, Integer::sum);
            List<String> factsByPredicate = new ArrayList<>();
            for (String predicate : domain.predicates.keySet())
                if (domain.fluent.contains(predicate))
                    factsByPredicate.add(predicate + "=" + counts.getOrDefault(predicate, 0));
            groundingLines.add(headed("facts by predicate:", factsByPredicate));
            groundingLines.add("facts:");
            for (int i = 0; i < problem.facts.size(); i++)
                groundingLines.add("  " + i + " " + problem.facts.get(i));
            groundingLines.add("actions:");
            for (Grounding.Action action : problem.actions)
                groundingLines.add(
                    "  " + action.number() + " " + action.text() + " cost=" + action.cost() +
                    " pre=" + numberList(action.pre()) + " neg=" + numberList(action.neg()) +
                    " add=" + numberList(action.add()) + " del=" + numberList(action.delete()));
        }
        BitSet initialReport(Grounding.Problem problem, Heuristics evaluator) {
            int[] values = evaluator.values(problem.initial);
            BitSet landmarks = evaluator.landmarks(problem.initial);
            if (landmarks == null)
                landmarks = new BitSet();
            List<Integer> relaxed = evaluator.relaxedPlan(problem.initial);
            if (relaxed == null)
                relaxed = List.of();
            planLines.add("initial h: " + heuristicText(values));
            planLines.add("landmarks: " + landmarks.cardinality());
            for (int number : Grounding.numbers(landmarks))
                planLines.add("  " + problem.facts.get(number));
            planLines.add("relaxed plan: length=" + relaxed.size() +
                          " cost=" + valueText(values[3]));
            for (int number : relaxed)
                planLines.add("  " + problem.actions.get(number).text());
            planLines.add(
                headed("helpful:", actionTexts(problem, evaluator.helpful(problem.initial))));
            return landmarks;
        }
        void planReport(Grounding.Problem problem, String tag, List<Integer> plan, BitSet landmarks,
                        Map<List<Integer>, String> earlier) {
            String first = earlier.computeIfAbsent(plan, p -> tag);
            planLines.add("plan: length=" + plan.size() + " cost=" + planCost(problem, plan) +
                          (first.equals(tag) ? "" : " (same as " + first + ")"));
            for (int i = 0; i < plan.size(); i++)
                planLines.add("  " + (i + 1) + " " + problem.actions.get(plan.get(i)).text());
            Map<String, Integer> counts = new HashMap<>();
            for (int number : plan)
                counts.merge(problem.actions.get(number).source().name(), 1, Integer::sum);
            List<String> schemas = new ArrayList<>();
            for (PddlParser.Schema schema : domain.actions)
                if (counts.containsKey(schema.name()))
                    schemas.add(schema.name() + "=" + counts.get(schema.name()));
            planLines.add(headed("schemas:", schemas));
            List<List<Integer>> layers = parallelize(problem, plan);
            planLines.add("parallel: layers=" + layers.size());
            for (int i = 0; i < layers.size(); i++)
                planLines.add(headed("  " + (i + 1) + ":", actionTexts(problem, layers.get(i))));
            List<Integer> improved = improve(problem, plan);
            int removed = plan.size() - improved.size();
            planLines.add("improved: length=" + improved.size() +
                          " cost=" + planCost(problem, improved) + " removed=" + removed);
            if (removed > 0)
                for (int i = 0; i < improved.size(); i++)
                    planLines.add("  " + (i + 1) + " " +
                                  problem.actions.get(improved.get(i)).text());
            BitSet reached = reachedLandmarks(problem, plan, landmarks);
            planLines.add("landmarks reached: " + reached.cardinality() + "/" +
                          landmarks.cardinality());
            BitSet missed = (BitSet)landmarks.clone();
            missed.andNot(reached);
            for (int number : Grounding.numbers(missed))
                planLines.add("  missed " + problem.facts.get(number));
            Validation checked = validateSteps(domain, problem.source, planSteps(problem, plan)),
                       checkedImproved =
                           validateSteps(domain, problem.source, planSteps(problem, improved));
            validationLines.add(tag + ": " + checked.verdict());
            validationLines.add("  parallel: " + validateParallel(problem, layers));
            validationLines.add("  improved: " + checkedImproved.verdict());
            validatedPlans++;
            if (checked.status().equals("valid"))
                validPlans++;
        }
        void searchResultReport(Grounding.Problem problem, String tag, Search.Result outcome,
                                BitSet landmarks, Map<List<Integer>, String> earlier) {
            planLines.add("-- " + tag + " --");
            if (!problem.unreachable.isEmpty()) {
                planLines.add("result: FAIL (unreachable goal)");
                return;
            }
            planLines.add(
                "result: " + (outcome.solved() ? "solved" : "FAIL (" + outcome.status() + ")") +
                " expanded=" + outcome.expanded() + " generated=" + outcome.generated());
            if (outcome.solved())
                planReport(problem, tag, outcome.plan(), landmarks, earlier);
        }
        void graphReport(Grounding.Problem problem, GraphPlan.Result outcome, int complements) {
            if (!problem.unreachable.isEmpty()) {
                graphLines.add("result: FAIL (unreachable goal)");
                return;
            }
            graphLines.add("complementary facts: " + complements);
            graphLines.addAll(outcome.lines());
            Search.Result search = outcome.search();
            String counts = " searched=" + search.expanded() + " memo_hits=" + outcome.memoHits() +
                            " tried=" + search.generated();
            if (search.solved()) {
                graphLines.add("result: solved levels=" + outcome.layers().size() +
                               " length=" + search.plan().size() +
                               " cost=" + planCost(problem, search.plan()) + counts);
                for (int i = 0; i < outcome.layers().size(); i++)
                    graphLines.add(headed("layer " + (i + 1) + ":",
                                          actionTexts(problem, outcome.layers().get(i))));
            } else
                graphLines.add("result: FAIL (" + search.status() + ")" + counts);
        }
        void profileReport(Grounding.Problem problem, Heuristics evaluator, String tag,
                           List<Integer> plan) {
            BitSet state = problem.initial;
            int remaining = planCost(problem, plan);
            int[] overestimates = new int[Heuristics.NAMES.size()];
            planLines.add("-- profile (" + tag + ") --");
            for (int position = 0; position <= plan.size(); position++) {
                int[] values = evaluator.values(state);
                planLines.add("  " + position + ": h*=" + remaining + " " + heuristicText(values));
                for (int i = 0; i < values.length; i++)
                    if (values[i] == Heuristics.INF || values[i] > remaining)
                        overestimates[i]++;
                if (position < plan.size()) {
                    Grounding.Action action = problem.actions.get(plan.get(position));
                    state = Search.apply(action, state);
                    remaining -= action.cost();
                }
            }
            List<String> counts = new ArrayList<>();
            for (int i = 0; i < overestimates.length; i++)
                counts.add(Heuristics.NAMES.get(i) + "=" + overestimates[i]);
            planLines.add("overestimates: " + String.join(" ", counts));
            planLines.add("-- causal links (" + tag + ") --");
            Map<Integer, Integer> suppliers = new HashMap<>();
            for (int i = 0; i < plan.size(); i++) {
                Grounding.Action action = problem.actions.get(plan.get(i));
                List<String> links = new ArrayList<>();
                for (int fact : Grounding.numbers(action.pre()))
                    links.add(problem.facts.get(fact) + "<-" + suppliers.getOrDefault(fact, 0));
                planLines.add(headed("  " + (i + 1) + " " + action.text() + ":", links));
                for (int fact : Grounding.numbers(action.add()))
                    suppliers.put(fact, i + 1);
            }
            List<String> links = new ArrayList<>();
            for (int fact : Grounding.numbers(problem.goal))
                links.add(problem.facts.get(fact) + "<-" + suppliers.getOrDefault(fact, 0));
            planLines.add(headed("  goal:", links));
        }
        void summarizeProblem(Grounding.Problem problem, List<Search.Result> outcomes,
                              Integer proof) {
            int solved = 0;
            Integer best = null;
            for (Search.Result outcome : outcomes)
                if (outcome.solved()) {
                    solved++;
                    int cost = planCost(problem, outcome.plan());
                    if (best == null || cost < best)
                        best = cost;
                }
            String optimal;
            if (proof != null)
                optimal = Integer.toString(planCost(problem, outcomes.get(proof).plan()));
            else {
                optimal = "unknown";
                for (Search.Result outcome : outcomes)
                    if (Set.of("unreachable goal", "dead end", "exhausted", "unreachable")
                            .contains(outcome.status()))
                        optimal = "none";
            }
            summaries.put(problem.name, new Summary(solved, best, optimal));
            List<Run> pairs = new ArrayList<>(settings.runs);
            pairs.add(new Run("graphplan", "none"));
            for (int i = 0; i < outcomes.size(); i++) {
                Search.Result outcome = outcomes.get(i);
                Run pair = pairs.get(i);
                Totals total = totals.get(i);
                total.expanded += outcome.expanded();
                total.generated += outcome.generated();
                String length = "-", cost = "-";
                if (outcome.solved()) {
                    int value = planCost(problem, outcome.plan());
                    length = Integer.toString(outcome.plan().size());
                    cost = Integer.toString(value);
                    total.solved++;
                    if (value == best)
                        total.best++;
                }
                comparisonLines.add(problem.name + "," + pair.algorithm() + "," + pair.heuristic() +
                                    "," + length + "," + cost + "," + outcome.expanded() + "," +
                                    outcome.generated());
            }
        }
        void solveProblem(PddlParser.Problem source) {
            validateProblem(domain, source);
            Grounding.Problem problem = Grounding.ground(domain, source);
            problems.put(problem.name, problem);
            groundingReport(problem);
            for (List<String> lines : List.of(planLines, graphLines, validationLines))
                lines.add("== problem " + problem.name + " ==");
            List<Search.Result> outcomes = new ArrayList<>();
            Map<List<Integer>, String> earlier = new HashMap<>();
            Integer proof = null;
            Heuristics evaluator = null;
            BitSet landmarks = new BitSet();
            boolean unreachable = !problem.unreachable.isEmpty();
            if (unreachable)
                planLines.add("initial h: unreachable goal");
            else {
                evaluator = new Heuristics(problem);
                evaluators.put(problem.name, evaluator);
                landmarks = initialReport(problem, evaluator);
            }
            for (int i = 0; i < settings.runs.size(); i++) {
                Run run = settings.runs.get(i);
                Search.Result outcome =
                    unreachable
                        ? Search.failure("unreachable goal", 0, 0)
                        : Search.run(problem, problem.initial, run.algorithm(), run.heuristic(),
                                     settings.budget, settings.weight, evaluator);
                outcomes.add(outcome);
                searchResultReport(problem, tags.get(i), outcome, landmarks, earlier);
                if (proof == null && outcome.solved() &&
                    (run.algorithm().equals("ucs") && run.heuristic().equals("none") ||
                     run.algorithm().equals("astar") && run.heuristic().equals("hmax")))
                    proof = i;
            }
            int complements = 0;
            GraphPlan.Result graph;
            if (unreachable)
                graph = new GraphPlan.Result(Search.failure("unreachable goal", 0, 0), List.of(),
                                             List.of(), 0);
            else {
                Transformed transformed = transformNegatives(problem);
                complements = transformed.complements();
                graph = new GraphPlan(transformed.actions(), transformed.initial(), problem.goal,
                                      settings.graphplan)
                            .run();
            }
            outcomes.add(graph.search());
            searchResultReport(problem, "graphplan", graph.search(), landmarks, earlier);
            graphReport(problem, graph, complements);
            if (proof != null)
                profileReport(problem, evaluator, tags.get(proof), outcomes.get(proof).plan());
            summarizeProblem(problem, outcomes, proof);
            for (List<String> lines : List.of(planLines, graphLines, validationLines))
                lines.add("");
        }
        void summaryReport() {
            planLines.add("== summary ==");
            for (var entry : summaries.entrySet()) {
                Summary summary = entry.getValue();
                planLines.add(
                    entry.getKey() + ": solved=" + summary.solved() + "/" + tags.size() +
                    " best=" + (summary.best() == null ? "-" : summary.best().toString()) +
                    " optimal=" + summary.optimal());
            }
            for (int i = 0; i < tags.size(); i++) {
                Totals total = totals.get(i);
                planLines.add(tags.get(i) + ": solved=" + total.solved + " best=" + total.best +
                              " expanded=" + total.expanded + " generated=" + total.generated);
            }
        }
        List<Integer> mappedSteps(Grounding.Problem problem, List<Grounding.Step> steps) {
            List<Integer> plan = new ArrayList<>();
            for (Grounding.Step step : steps)
                plan.add(problem.actionNumbers.get(step));
            return plan;
        }
        void repairCandidate(Grounding.Problem problem, Candidate candidate, Validation checked) {
            if (!problem.unreachable.isEmpty()) {
                validationLines.add("  repair: FAIL (unreachable goal)");
                return;
            }
            List<Integer> prefix =
                mappedSteps(problem, candidate.steps.subList(0, checked.correct()));
            BitSet state = problem.initial;
            for (int number : prefix)
                state = Search.apply(problem.actions.get(number), state);
            Search.Result outcome =
                Search.run(problem, state, settings.repair.algorithm(), settings.repair.heuristic(),
                           settings.budget, settings.weight, evaluators.get(problem.name));
            if (!outcome.solved()) {
                validationLines.add("  repair: FAIL (" + outcome.status() + ")");
                return;
            }
            List<Integer> repaired = new ArrayList<>(prefix);
            repaired.addAll(outcome.plan());
            Validation validation =
                validateSteps(domain, problem.source, planSteps(problem, repaired));
            validationLines.add("  repair: kept=" + prefix.size() +
                                " added=" + outcome.plan().size() + " " + validation.verdict());
            for (int i = 0; i < repaired.size(); i++)
                validationLines.add("    " + (i + 1) + " " +
                                    problem.actions.get(repaired.get(i)).text());
        }
        void candidateReport() {
            validationLines.add("== candidates ==");
            for (Candidate candidate : candidates) {
                Grounding.Problem problem = problems.get(candidate.problem);
                Validation checked = validateSteps(domain, problem.source, candidate.steps);
                String heading = "candidate " + candidate.number + " " + candidate.problem + " " +
                                 candidate.label + ": ";
                if (checked.status().equals("valid")) {
                    validCandidates++;
                    validationLines.add(heading + checked.verdict());
                    List<Integer> mapped = mappedSteps(problem, candidate.steps),
                                  improved = improve(problem, mapped);
                    Integer best = summaries.get(problem.name).best();
                    validationLines.add("  improved: length=" + improved.size() +
                                        " cost=" + planCost(problem, improved) +
                                        " removed=" + (mapped.size() - improved.size()) +
                                        " best known=" + (best == null ? "-" : best.toString()));
                } else {
                    validationLines.add(heading + checked.status());
                    for (String message : checked.messages())
                        validationLines.add("  " + message);
                    repairCandidate(problem, candidate, checked);
                }
            }
            validationLines.add("");
            validationLines.add("== summary ==");
            validationLines.add("plans: " + validatedPlans + " valid: " + validPlans);
            validationLines.add("candidates: " + candidates.size() + " valid: " + validCandidates);
        }
        void writeReports() throws Exception {
            Files.createDirectories(Path.of("output"));
            Map<String, List<String>> reports = new LinkedHashMap<>();
            reports.put("grounding.txt", groundingLines);
            reports.put("plans.txt", planLines);
            reports.put("graphplan.txt", graphLines);
            reports.put("validation.txt", validationLines);
            reports.put("comparison.csv", comparisonLines);
            for (var entry : reports.entrySet())
                Files.writeString(Path.of("output", entry.getKey()),
                                  String.join("\n", entry.getValue()) + "\n",
                                  StandardCharsets.US_ASCII);
        }
        void run() throws Exception {
            domainReport();
            for (PddlParser.Problem source : sources)
                solveProblem(source);
            summaryReport();
            candidateReport();
            writeReports();
        }
    }
    public static void main(String[] args) throws Exception { new Planner().run(); }
}

import java.util.*;
final class PddlParser {
    sealed interface Expression permits Word, Sequence {}
    record Word(String value) implements Expression {}
    record Sequence(List<Expression> values) implements Expression {}
    record Typed(String name, String type) {}
    record Atom(String predicate, List<String> terms) {
        Atom { terms = List.copyOf(terms); }
        public String toString() {
            return "(" + predicate + (terms.isEmpty() ? "" : " " + String.join(" ", terms)) + ")";
        }
    }
    record Literal(boolean positive, Atom atom) {}
    record Schema(String name, List<Typed> parameters, List<Literal> condition,
                  List<Literal> effects, int cost) {}
    static final class Domain {
        String name;
        Map<String, String> parents = new LinkedHashMap<>();
        List<String> typeOrder = new ArrayList<>();
        Map<String, List<String>> predicates = new LinkedHashMap<>();
        List<Schema> actions = new ArrayList<>();
        Map<String, Schema> byName = new LinkedHashMap<>();
        Set<String> fluent = new HashSet<>(), statics = new HashSet<>();
        List<String> diagnostics = new ArrayList<>();
        Domain(String name) {
            this.name = name;
            parents.put("object", null);
            typeOrder.add("object");
        }
    }
    static final class Problem {
        String name;
        Map<String, String> objects = new LinkedHashMap<>();
        List<Atom> initial = new ArrayList<>(), goals = new ArrayList<>();
        List<String> diagnostics = new ArrayList<>();
        Problem(String name) { this.name = name; }
    }
    static String word(Expression expression) { return ((Word)expression).value(); }
    static List<Expression> list(Expression expression) { return ((Sequence)expression).values(); }
    static List<String> words(List<Expression> expressions) {
        List<String> result = new ArrayList<>();
        for (Expression expression : expressions)
            result.add(word(expression));
        return result;
    }
    static List<Expression> expressions(String text) {
        List<Expression> roots = new ArrayList<>();
        Deque<List<Expression>> stack = new ArrayDeque<>();
        stack.push(roots);
        StringBuilder cleaned = new StringBuilder();
        for (String line : text.split("\n", -1)) {
            int comment = line.indexOf(';');
            cleaned.append(comment < 0 ? line : line.substring(0, comment)).append('\n');
        }
        String source = cleaned.toString();
        for (int i = 0; i < source.length();) {
            char c = source.charAt(i);
            if (c == ' ' || c == '\n') {
                i++;
                continue;
            }
            if (c == '(') {
                List<Expression> child = new ArrayList<>();
                stack.peek().add(new Sequence(child));
                stack.push(child);
                i++;
            } else if (c == ')') {
                stack.pop();
                i++;
            } else {
                int start = i;
                while (i < source.length() && " ()\n".indexOf(source.charAt(i)) < 0)
                    i++;
                stack.peek().add(new Word(source.substring(start, i)));
            }
        }
        return roots;
    }
    static List<Typed> typedList(List<String> words) {
        List<Typed> result = new ArrayList<>();
        List<String> pending = new ArrayList<>();
        for (int i = 0; i < words.size();) {
            String word = words.get(i);
            if (word.equals("-")) {
                String type = words.get(i + 1);
                for (String name : pending)
                    result.add(new Typed(name, type));
                pending.clear();
                i += 2;
            } else {
                pending.add(word);
                i++;
            }
        }
        for (String name : pending)
            result.add(new Typed(name, "object"));
        return result;
    }
    static Atom atom(Expression expression) {
        List<Expression> values = list(expression);
        return new Atom(word(values.getFirst()), words(values.subList(1, values.size())));
    }
    static List<Expression> elements(Expression expression, boolean empty) {
        List<Expression> values = list(expression);
        boolean conjunction = !values.isEmpty() && word(values.getFirst()).equals("and");
        for (Expression item : values.subList(1, values.size()))
            if (!(item instanceof Sequence))
                conjunction = false;
        return conjunction && (empty || values.size() > 1) ? values.subList(1, values.size())
                                                           : List.of(expression);
    }
    static Literal literal(Expression expression) {
        List<Expression> values = list(expression);
        if (word(values.getFirst()).equals("not") && values.size() == 2 &&
            values.get(1) instanceof Sequence)
            return new Literal(false, atom(values.get(1)));
        return new Literal(true, atom(expression));
    }
    static Domain readDomain(String text) {
        List<Expression> expression = list(expressions(text).getFirst());
        Domain domain = new Domain(word(list(expression.get(1)).get(1)));
        for (Expression raw : expression.subList(2, expression.size())) {
            List<Expression> section = list(raw);
            String kind = word(section.getFirst());
            if (kind.equals(":types")) {
                List<String> words = words(section.subList(1, section.size()));
                for (String name : words)
                    if (!name.equals("-") && !domain.parents.containsKey(name)) {
                        domain.parents.put(name, "object");
                        domain.typeOrder.add(name);
                    }
                for (Typed type : typedList(words))
                    domain.parents.put(type.name(), type.type());
            } else if (kind.equals(":predicates"))
                for (Expression declaration : section.subList(1, section.size())) {
                    List<Expression> values = list(declaration);
                    List<String> types = new ArrayList<>();
                    for (Typed parameter : typedList(words(values.subList(1, values.size()))))
                        types.add(parameter.type());
                    domain.predicates.put(word(values.getFirst()), types);
                }
            else if (kind.equals(":action")) {
                Map<String, Expression> fields = new HashMap<>();
                for (int i = 2; i < section.size(); i += 2)
                    fields.put(word(section.get(i)), section.get(i + 1));
                List<Literal> condition = new ArrayList<>();
                if (fields.containsKey(":precondition"))
                    for (Expression item : elements(fields.get(":precondition"), true))
                        condition.add(literal(item));
                List<Literal> effects = new ArrayList<>();
                int cost = 1;
                for (Expression item : elements(fields.get(":effect"), false)) {
                    List<Expression> value = list(item);
                    if (word(value.getFirst()).equals("increase") && value.size() == 3 &&
                        list(value.get(1)).size() == 1 &&
                        word(list(value.get(1)).getFirst()).equals("total-cost"))
                        cost = Integer.parseInt(word(value.get(2)));
                    else
                        effects.add(literal(item));
                }
                domain.actions.add(new Schema(word(section.get(1)),
                                              typedList(words(list(fields.get(":parameters")))),
                                              condition, effects, cost));
            }
        }
        return domain;
    }
    static List<Problem> readProblems(String text) {
        List<Problem> problems = new ArrayList<>();
        for (Expression raw : expressions(text)) {
            List<Expression> expression = list(raw);
            Problem problem = new Problem(word(list(expression.get(1)).get(1)));
            Map<String, List<Expression>> sections = new HashMap<>();
            for (Expression item : expression.subList(2, expression.size())) {
                List<Expression> section = list(item);
                sections.put(word(section.getFirst()), section.subList(1, section.size()));
            }
            for (Typed object : typedList(words(sections.get(":objects"))))
                problem.objects.put(object.name(), object.type());
            for (Expression item : sections.get(":init"))
                problem.initial.add(atom(item));
            for (Expression item : elements(sections.get(":goal").getFirst(), false))
                problem.goals.add(atom(item));
            problems.add(problem);
        }
        return problems;
    }
}

import java.util.*;
final class Search {
    record Result(String status, int expanded, int generated, List<Integer> plan) {
        Result { plan = List.copyOf(plan); }
        boolean solved() { return status.equals("solved"); }
    }
    record Node(BitSet state, int g, int depth, Node parent, int action) {}
    record Entry(int f, int h, int serial, Node node) {}
    record Local(BitSet state, List<Integer> path) {}
    static Result failure(String status, int expanded, int generated) {
        return new Result(status, expanded, generated, List.of());
    }
    static boolean applicable(Grounding.Action action, BitSet state) {
        return Grounding.contains(state, action.pre()) && !state.intersects(action.neg());
    }
    static BitSet apply(Grounding.Action action, BitSet state) {
        BitSet result = (BitSet)state.clone();
        result.andNot(action.delete());
        result.or(action.add());
        return result;
    }
    static List<Integer> reconstruct(Node node) {
        List<Integer> plan = new ArrayList<>();
        for (Node current = node; current.parent() != null; current = current.parent())
            plan.add(current.action());
        Collections.reverse(plan);
        return plan;
    }
    static int priority(String algorithm, Node node, int h, int weight) {
        return switch (algorithm) {
            case "bfs" -> node.depth();
            case "ucs" -> node.g();
            case "gbfs" -> h;
            default -> node.g() + h *(algorithm.equals("wastar") ? weight : 1);
        };
    }
    static Result bestFirst(Grounding.Problem problem, BitSet start, String algorithm,
                            String heuristic, int budget, int weight, Heuristics evaluator) {
        int initialH = evaluator.value(heuristic, start);
        if (initialH == Heuristics.INF)
            return failure("dead end", 0, 0);
        Node first = new Node(start, 0, 0, null, -1);
        PriorityQueue<Entry> open = new PriorityQueue<>(
            Comparator.comparingInt(Entry::f).thenComparingInt(Entry::h).thenComparingInt(
                Entry::serial));
        open.add(new Entry(priority(algorithm, first, initialH, weight), initialH, 0, first));
        Map<BitSet, Integer> best = new HashMap<>();
        best.put(start, 0);
        int serial = 1, expanded = 0, generated = 0;
        boolean reopen = Set.of("ucs", "astar", "wastar").contains(algorithm);
        while (!open.isEmpty()) {
            Node node = open.remove().node();
            if (reopen && node.g() > best.get(node.state()))
                continue;
            if (Grounding.contains(node.state(), problem.goal))
                return new Result("solved", expanded, generated, reconstruct(node));
            if (expanded == budget)
                return failure("budget", expanded, generated);
            expanded++;
            for (Grounding.Action action : problem.actions)
                if (applicable(action, node.state())) {
                    BitSet state = apply(action, node.state());
                    generated++;
                    int cost = node.g() + action.cost();
                    Integer previous = best.get(state);
                    if (previous != null && (!reopen || previous <= cost))
                        continue;
                    best.put(state, cost);
                    int h = evaluator.value(heuristic, state);
                    if (h == Heuristics.INF)
                        continue;
                    Node child = new Node(state, cost, node.depth() + 1, node, action.number());
                    open.add(new Entry(priority(algorithm, child, h, weight), h, serial++, child));
                }
        }
        return failure("exhausted", expanded, generated);
    }
    static Result hillClimbing(Grounding.Problem problem, BitSet start, String heuristic,
                               int budget, Heuristics evaluator) {
        BitSet current = start;
        List<Integer> plan = new ArrayList<>();
        int currentH = evaluator.value(heuristic, current), expanded = 0, generated = 0;
        if (currentH == Heuristics.INF)
            return failure("dead end", 0, 0);
        while (!Grounding.contains(current, problem.goal)) {
            Deque<Local> queue = new ArrayDeque<>();
            queue.add(new Local(current, List.of()));
            Set<BitSet> visited = new HashSet<>();
            visited.add(current);
            boolean improved = false;
            while (!queue.isEmpty() && !improved) {
                Local local = queue.remove();
                if (expanded == budget)
                    return failure("budget", expanded, generated);
                expanded++;
                for (int number : evaluator.helpful(local.state())) {
                    BitSet successor = apply(problem.actions.get(number), local.state());
                    generated++;
                    if (!visited.add(successor))
                        continue;
                    int h = evaluator.value(heuristic, successor);
                    if (h == Heuristics.INF)
                        continue;
                    List<Integer> path = new ArrayList<>(local.path());
                    path.add(number);
                    if (h < currentH) {
                        plan.addAll(path);
                        current = successor;
                        currentH = h;
                        improved = true;
                        break;
                    }
                    queue.add(new Local(successor, path));
                }
            }
            if (!improved)
                return failure("stuck", expanded, generated);
        }
        return new Result("solved", expanded, generated, plan);
    }
    static Result run(Grounding.Problem problem, BitSet start, String algorithm, String heuristic,
                      int budget, int weight, Heuristics evaluator) {
        return algorithm.equals("ehc")
            ? hillClimbing(problem, start, heuristic, budget, evaluator)
            : bestFirst(problem, start, algorithm, heuristic, budget, weight, evaluator);
    }
}
